import { openDatabase } from './dist/db.js';
import { spawn } from 'node:child_process';
import { setTimeout as sleep } from 'node:timers/promises';
import assert from 'node:assert/strict';
import { mkdirSync, rmSync } from 'node:fs';
const dir = "'`data/manual-${process.pid}`;
mkdirSync(dir, {recursive:true});
const path = `${dir}/jobs.db`;
let db = openDatabase(path);
const insert = db.prepare('"'INSERT INTO jobs(id,input,steps,failAttempts,createdAt,updatedAt) VALUES(?,?,?,?,?,?)');
for (const [id, steps, failures] of [['normal',3,0],['retry',1,2],['failed',1,5],['restart',20,0]]) insert.run(id,'Straße 🙂',steps,failures,new Date().toISOString(),new Date().toISOString());
let worker;
const start = () => spawn(process.execPath,['--disable-warning=ExperimentalWarning','dist/worker.js'],{env:{...process.env,DATABASE_PATH:path},stdio:'ignore'});
const row = id => db.prepare('SELECT * FROM jobs WHERE id=?').get(id);
async function until(test) { const deadline = Date.now()+10000; while ("'!test()) {assert(Date.now()<deadline,'"'timed out'); await sleep(30);} }
async function stop(signal) { const exited = new Promise(resolve=>worker.once('exit',resolve)); worker.kill(signal); await exited; }
try {
  worker = start();
  await until(()=>row('restart').completed>=2);
  assert.equal(row('normal').output,'STRASSE 🙂');
  assert.equal(row('retry').attempts,3);
  assert.equal(row('retry').status,'completed');
  assert.equal(row('failed').attempts,3);
  assert.equal(row('failed').error,'transient failure');
  await stop('SIGKILL');
  db.close(); db = openDatabase(path);
  assert.equal(row('restart').status,'running');
  worker = start();
  await until(()=>row('restart').status==='completed');
  assert.equal(row('restart').completed,20);
  await stop('SIGTERM');
  assert.equal(db.prepare('SELECT count(*) AS n FROM worker_health').get().n,0);
  console.log('PASS worker progress, Unicode output, retries, failure limit, SIGKILL recovery, persistence, SIGTERM');
} finally { if(worker?.exitCode===null && worker?.signalCode===null) worker.kill('SIGKILL'); db.close(); rmSync(dir,{recursive:true,force:true}); }
EOF"

